#!/usr/bin/env bash
# Step 6: TLS at the two edges of the mesh.
#   ingress: an HTTPS listener on the Gateway (ingress/gateway-https.yaml),
#            with a CA and certificate generated by tools/gen-tls-cert.sh;
#   egress:  TLS origination for api.github.com (egress/): the application
#            calls http://api.github.com and its sidecar opens the TLS
#            connection to port 443. Needs Internet egress from the kind nodes;
#            sends 2 requests to api.github.com in total.
# The JWT policies of step 05 are removed first: this step is about TLS.
set -euo pipefail
# shellcheck source=/dev/null
source "$(dirname "${BASH_SOURCE[0]}")/lib.sh"
assert_lab_context

NS="payments"
GW_NS="payments-ingress"
HOST="api.payments.example"
TLS_DIR="${OUT}/tls"
N=5

reset_security "${GW_NS}"
k -n "${NS}" delete serviceentry,destinationrule --all >/dev/null
apply_file "${REPO_ROOT}/authz/12-payments-api-allow-ingress.yaml"

step "Certificate: tools/gen-tls-cert.sh (private CA + leaf for ${HOST})"
bash "${REPO_ROOT}/tools/gen-tls-cert.sh" "${TLS_DIR}" | sed 's/^/    /'
k -n "${GW_NS}" create secret tls payments-gateway-cert \
  --cert="${TLS_DIR}/server.crt" --key="${TLS_DIR}/server.key" --dry-run=client -o yaml | k apply -f - >/dev/null
note "Secret ${GW_NS}/payments-gateway-cert (kubernetes.io/tls)"

step "HTTPS listener: ingress/gateway.yaml then ingress/gateway-https.yaml"
apply_file "${REPO_ROOT}/ingress/gateway.yaml"
apply_file "${REPO_ROOT}/ingress/gateway-https.yaml"
apply_file "${REPO_ROOT}/ingress/httproute.yaml"
k -n "${GW_NS}" wait --for=condition=Programmed gateway/payments-gateway --timeout=180s >/dev/null
k -n "${GW_NS}" rollout status deploy/payments-gateway-istio --timeout=180s >/dev/null
listeners="$(k -n "${GW_NS}" get gateway payments-gateway -o json | jq -r '[.status.listeners[] | "\(.name):attachedRoutes=\(.attachedRoutes):Programmed=\((.conditions[] | select(.type == "Programmed") | .status))"] | join(" ")')"
note "${listeners}"
expect_eq "both listeners programmed, the route attached to each" "http:attachedRoutes=1:Programmed=True https:attachedRoutes=1:Programmed=True" "${listeners}"
IP="$(k -n "${GW_NS}" get svc payments-gateway-istio -o jsonpath='{.spec.clusterIP}')"
# The CA travels as an argument, not on stdin: kubectl exec -i lost it once
# (an empty file) in the lab runs.
# shellcheck disable=SC2016 # runs in the pod shell
k -n legacy exec deploy/settlement-batch -c app -- sh -c 'printf "%s\n" "$1" > /tmp/payments-lab-ca.crt' sh "$(cat "${TLS_DIR}/ca.crt")"
expect_eq "lab CA copied into settlement-batch" "$(openssl x509 -in "${TLS_DIR}/ca.crt" -noout -fingerprint -sha256)" \
  "$(k -n legacy exec deploy/settlement-batch -c app -- cat /tmp/payments-lab-ca.crt | openssl x509 -noout -fingerprint -sha256)"
URL="https://${HOST}/v1/payments/1"
wait_for 90 "200 0" req legacy settlement-batch "${URL}" --resolve "${HOST}:443:${IP}" --cacert /tmp/payments-lab-ca.crt || true
c="$(codes legacy settlement-batch "${N}" "${URL}" --resolve "${HOST}:443:${IP}" --cacert /tmp/payments-lab-ca.crt)"
expect_eq "HTTPS with the lab CA trusted: 200" "200=${N}" "${c}"
hs="$(k -n legacy exec deploy/settlement-batch -c app -- curl -sv -o /dev/null --max-time 10 \
  --resolve "${HOST}:443:${IP}" --cacert /tmp/payments-lab-ca.crt "${URL}" 2>&1 | grep -E 'SSL connection using|subject:|issuer:|^< HTTP' || true)"
printf '%s\n' "${hs}" | sed 's/^/      /'
expect_match "TLS 1.3 handshake" 'SSL connection using TLSv1\.3' "${hs}"
expect_match "server certificate for ${HOST}" 'subject: O=Payments Lab; CN=api\.payments\.example' "${hs}"
expect_match "issued by the lab CA" 'issuer: O=Payments Lab; CN=Payments Lab CA' "${hs}"
expect_match "HTTP/2 negotiated over TLS (ALPN)" '^< HTTP/2 200' "${hs}"
r="$(req legacy settlement-batch "${URL}" --resolve "${HOST}:443:${IP}")"
expect_eq "without the CA, curl refuses the certificate (exit 60)" "000 60" "${r}"
expect_match "curl's error" 'curl: \(60\) SSL certificate OpenSSL verify result: unable to get local issuer certificate \(20\)' \
  "$(req_full legacy settlement-batch "${URL}" --resolve "${HOST}:443:${IP}" -o /dev/null)"
c="$(codes legacy settlement-batch "${N}" "http://${HOST}/v1/payments/1" --resolve "${HOST}:80:${IP}")"
expect_eq "the HTTP listener still answers too (remove it, or redirect, when HTTPS is the only door)" "200=${N}" "${c}"

step "Egress TLS origination: egress/serviceentry-github.yaml + egress/destinationrule-github-tls.yaml"
apply_file "${REPO_ROOT}/egress/serviceentry-github.yaml"
apply_file "${REPO_ROOT}/egress/destinationrule-github-tls.yaml"
# cluster_tls -> the TLS settings istiod pushed for api.github.com:80 to payments-api's sidecar
cluster_tls() {
  ictl proxy-config cluster deploy/payments-api -n "${NS}" --fqdn api.github.com --port 80 -o json \
    | jq -c '.[0] | {
        tls: ([.. | objects | select(."@type"? == "type.googleapis.com/envoy.extensions.transport_sockets.tls.v3.UpstreamTlsContext")] | length > 0),
        ca: ([.. | objects | select(has("validationContextSdsSecretConfig")) | .validationContextSdsSecretConfig.name] | first),
        autoSni: .typedExtensionProtocolOptions["envoy.extensions.upstreams.http.v3.HttpProtocolOptions"].upstreamHttpProtocolOptions.autoSni,
        autoSan: .typedExtensionProtocolOptions["envoy.extensions.upstreams.http.v3.HttpProtocolOptions"].upstreamHttpProtocolOptions.autoSanValidation }'
}
wait_json 90 '.tls == true' cluster_tls || true
ct="$(cluster_tls)"; note "outbound|80||api.github.com on payments-api: ${ct}"
expect_eq "the sidecar originates TLS, verifies against the OS CA bundle, SNI and SAN from the Host header" \
  '{"tls":true,"ca":"file-root:system","autoSni":true,"autoSanValidation":true}' "$(jq -c '{tls, ca, autoSni, autoSanValidation: .autoSan}' <<< "${ct}")"
since="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
# One request; the response headers tell who answered. Unauthenticated calls
# to api.github.com are limited to 60 per hour per source IP, so a shared
# egress IP can get 403 "API rate limit exceeded": that is still GitHub
# answering over the TLS connection the sidecar opened, and it is accepted
# here only with x-ratelimit-remaining: 0.
hdrs="$(req_full "${NS}" payments-api http://api.github.com/zen -o /dev/null -D - | tr -d '\r')"
code="$(sed -n '1s/^HTTP\/[0-9.]* \([0-9]*\).*/\1/p' <<< "${hdrs}")"
remaining="$(sed -n 's/^x-ratelimit-remaining: //Ip' <<< "${hdrs}")"
note "payments-api: curl http://api.github.com/zen -> HTTP ${code} (x-ratelimit-remaining: ${remaining:-?})"
# (the sidecar rewrites the server header to "envoy"; GitHub's own request id survives)
expect_match "the answer comes from GitHub (x-github-request-id header)" '^x-github-request-id: [0-9A-F:]+$' "$(grep -i '^x-github-request-id:' <<< "${hdrs}")"
if [ "${code}" = "403" ]; then
  expect_eq "403 is GitHub's rate limit for this egress IP, not the mesh" "0" "${remaining}"
else
  expect_eq "plain HTTP from the application, 200 from GitHub" "200" "${code}"
fi
sleep 3
log="$(k -n "${NS}" logs deploy/payments-api -c istio-proxy --since-time="${since}" 2>/dev/null | grep -F '"GET /zen HTTP/1.1"' | tail -1 || true)"
note "sidecar access log: ${log}"
expect_match "logged by name, as HTTP: method, path, GitHub's status, authority api.github.com" "\"GET /zen HTTP/1.1\" ${code} - via_upstream .* \"api\\.github\\.com\" " "${log}"
expect_match "the upstream connection went to port 443 through cluster outbound|80||api.github.com" \
  '"[0-9.]+:443" outbound\|80\|\|api\.github\.com ' "${log}"

step "Without the DestinationRule, the same request is plain HTTP sent to port 443"
k -n "${NS}" delete destinationrule api-github-com >/dev/null
wait_json 90 '.tls == false' cluster_tls || true
since="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
r="$(req "${NS}" payments-api http://api.github.com/zen)"; note "-> ${r}"
expect_eq "503 from the sidecar" "503 0" "${r}"
sleep 3
log="$(k -n "${NS}" logs deploy/payments-api -c istio-proxy --since-time="${since}" 2>/dev/null | grep -F '"GET /zen HTTP/1.1"' | tail -1 || true)"
note "sidecar access log: ${log}"
expect_match "upstream reset: GitHub's port 443 closed the plain-text connection (UC)" '" 503 UC upstream_reset_before_response_started\{connection_termination\} ' "${log}"
apply_file "${REPO_ROOT}/egress/destinationrule-github-tls.yaml"

step "Does SIMPLE without caCertificates verify the server? egress/tls-origination-verify-probe.yaml"
out="$(istioctl analyze --use-kube=false --all-namespaces "${REPO_ROOT}/egress/destinationrule-github-tls.yaml" 2>&1 || true)"
expect_match "istioctl analyze says it does not (IST0129)" 'IST0129.*TLS mode set to SIMPLE but no caCertificates are set to validate server identity' "${out}"
apply_file "${REPO_ROOT}/egress/tls-origination-verify-probe.yaml"
wait_json 90 '.tls == true' eval "ictl proxy-config cluster deploy/payments-api -n ${NS} --fqdn api.payments.example --port 80 -o json | jq -c '{tls: ([.. | objects | select(.\"@type\"? == \"type.googleapis.com/envoy.extensions.transport_sockets.tls.v3.UpstreamTlsContext\")] | length > 0)}'" || true
since="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
r="$(req "${NS}" payments-api "http://${HOST}/v1/payments/1" --resolve "${HOST}:80:${IP}")"
note "payments-api -> http://${HOST} (TLS originated to the lab Gateway, lab CA not in the OS bundle) -> ${r}"
expect_eq "the sidecar refuses the certificate: 503" "503 0" "${r}"
sleep 3
log="$(k -n "${NS}" logs deploy/payments-api -c istio-proxy --since-time="${since}" 2>/dev/null | grep -F '"api.payments.example"' | tail -1 || true)"
note "sidecar access log: ${log:0:260}"
expect_match "access log: UF with CERTIFICATE_VERIFY_FAILED, unable to get local issuer certificate" \
  '" 503 URX,UF .*CERTIFICATE_VERIFY_FAILED.*unable_to_get_local_issuer_certificate' "${log}"
yq 'select(.kind == "DestinationRule") | .spec.trafficPolicy.portLevelSettings[0].tls.insecureSkipVerify = true' \
  "${REPO_ROOT}/egress/tls-origination-verify-probe.yaml" | k apply -f - >/dev/null
note "the same DestinationRule with insecureSkipVerify: true (yq edit)"
wait_for 90 "200 0" req "${NS}" payments-api "http://${HOST}/v1/payments/1" --resolve "${HOST}:80:${IP}" || true
expect_eq "only insecureSkipVerify lets it through: 200" "200 0" "$(req "${NS}" payments-api "http://${HOST}/v1/payments/1" --resolve "${HOST}:80:${IP}")"
k -n "${NS}" delete serviceentry,destinationrule api-payments-example >/dev/null
finish
